WITH base AS (SELECT id, customer_id, device, browser, started_at, CASE WHEN browser = 'Safari' THEN 1 ELSE 0 END AS is_safari FROM sessions WHERE started_at > TIMESTAMP '2023-10-04 15:00:00' AND customer_id IS NOT NULL AND customer_id = 12) SELECT DATE_TRUNC('MONTH', started_at) AS activity_month, COUNT_IF(device = 'mobile') AS mobile_events, ROUND(SUM(is_safari) / NULLIF(COUNT(CASE WHEN browser = 'Chrome' THEN 1 END), 0), 2) AS is_safari_per_chrome, PERCENTILE_APPROX(is_safari, 0.5) AS is_safari_p50, ROUND(AVG(is_safari), 2) AS avg_is_safari FROM base GROUP BY DATE_TRUNC('MONTH', started_at) ORDER BY is_safari_p50
